            assert!(raw[0] < 8 * bound, "{kind} {index} c0.a bound");
            assert!(raw[1] < 8 * bound, "{kind} {index} c0.b bound");
            assert!(raw[2] < 4 * bound, "{kind} {index} c1.a bound");
            assert!(raw[3] < 4 * bound, "{kind} {index} c1.b bound");
