            c0: CM31::new(M31::ZERO, M31(P - 1)),
            c1: CM31::new(M31(P - 1), M31::ZERO),
        };
        let corpus = [QM31::ZERO, QM31::ONE, maximal, alternating, reversed];
        for encoded in 0..corpus.len().pow(4) {
            let mut index = encoded;
            let input = core::array::from_fn(|_| {
